            if (retVal.startsWith("/"))
                retVal = retVal.substring(1);
            if (!retVal.endsWith("/"))
                retVal = retVal + "/";

            return retVal;
        }
        return "";
    }

    private void putMapping(HashMap<String, String> mappings, String str, String str1) {
        mappings.put(str, str1);
    }

    @Override
